// 登记资源。页面会话登记时所有者就是这个人，可省略正文。树类型的正文是 AccessTreePut 的字段
type AppResourceRegisterRequest struct {
	// 树类型的根：已归档
	Archived bool `json:"archived,omitempty"`
	// 树类型的节点：是否继承上级名单，省略为 true
	Inherit bool `json:"inherit,omitempty"`
	// 所有者的 user id。应用自己的令牌必填（平铺类型）
	Owner string `json:"owner,omitempty"`
	// 树类型的节点：父节点；省略为根的顶层
	Parent string `json:"parent,omitempty"`
	// 树类型的根：edit 以下按已发布版本读
	PublishOnly bool `json:"publishOnly,omitempty"`
	// 树类型的节点：所在的根（顶层节点必填）
	Root string `json:"root,omitempty"`
	// 树类型的节点：在应用的回收站里
	Trashed bool `json:"trashed,omitempty"`
}

// 种类相关的参数（字段名是 snake_case）；哪个种类读哪些字段由服务在保存模板时检查
type AppEntitlementParams struct {
	// 满减金额（cash）
	AmountOffCents int `json:"amount_off_cents,omitempty"`
	// 每日上限（期卡）
	DailyCap int `json:"daily_cap,omitempty"`
	// 奖品说明
	Description string `json:"description,omitempty"`
	// 固定有效期结束，含当天
	EndsOn string `json:"ends_on,omitempty"`
	// 券的形式：cash、percent、service、code
	Form string `json:"form,omitempty"`
	// 奖品如何交付（对平台不透明）
	Fulfilment string `json:"fulfilment,omitempty"`
	// 最多减多少，0 为不封顶（percent）
	MaxOffCents int `json:"max_off_cents,omitempty"`
	// 折扣：减多少个百分点，1 到 99（percent）
	Percent int `json:"percent,omitempty"`
	// 订单退款时把券还回去（由调用方读到后作废核销单）
	RestoreOnRefund bool `json:"restore_on_refund,omitempty"`
	// 固定有效期开始，YYYY-MM-DD（券；覆盖 valid_days）
	StartsOn string `json:"starts_on,omitempty"`
	// 订单要达到的金额（cash、percent）
	ThresholdCents int `json:"threshold_cents,omitempty"`
	// 次数（count、count_period）
	TotalTimes int `json:"total_times,omitempty"`
	// 有效天数（period、count_period 必填）
	ValidDays int `json:"valid_days,omitempty"`
	// "grant"（默认）或 "first_use"
	ValidFrom string `json:"valid_from,omitempty"`
	// 每周上限（期卡）
	WeeklyCap int `json:"weekly_cap,omitempty"`
}

// 租户变化事件的输入
